import {initialWorkflow} from './workflow.mjs';
export const projects = [
 {id:'P01',name:'Home routines',client:'Northstar Robotics',code:'NR',color:'#64527d',target:420,accepted:286,submitted:332,firstReviews:316,firstPass:286,reviewed:316,qaRate:40,rate:8.5},
 {id:'P02',name:'Retail interactions',client:'Atlas Research',code:'AR',color:'#b88748',target:340,accepted:229,submitted:278,firstReviews:260,firstPass:229,reviewed:260,qaRate:26,rate:9},
 {id:'P03',name:'Workshop assembly',client:'Forma Intelligence',code:'FI',color:'#7772ab',target:280,accepted:197,submitted:226,firstReviews:219,firstPass:197,reviewed:219,qaRate:32,rate:11}
];
const first=['Amira','Mateo','Nora','Elias','Sofia','Leo','Maya','Omar','Lucia','Theo','Zara','Felix','Isla','Adam','Lina','Noah','Eva','Rami','Clara','Hugo'];
const last=['Bennett','Silva','Martin'];
export function initialState(){return {version:2,workers:Array.from({length:60},(_,i)=>({id:'FO-'+String(i+1).padStart(3,'0'),name:first[i%20]+' '+last[Math.floor(i/20)],region:['Toronto','Mexico City','São Paulo'][i%3],project:i<48?projects[Math.floor(i/16)].id:null,qualified:i%4===0?['P01','P02','P03']:[...new Set([projects[Math.floor(i/20)].id,projects[i%3].id,...(i<48?[projects[Math.floor(i/16)].id]:[])])],status:i===4||i===18?'Offline':i===33?'Absent':i>=48?'Available':'Collecting',units:2+(i%3),hourly:18+(i%5)*2,firstPass:84+(i*7%15)})),incidents:[{id:'INC-084',project:'P01',title:'Upload connectivity lost',detail:'Two collection devices require a connectivity check. Reassign qualified reserve capacity while the team lead investigates.',severity:'High',owner:'Maya Silva',status:'Open'},{id:'INC-083',project:'P02',title:'QA queue approaching deadline',detail:'Review capacity limits accepted delivery. Additional collectors alone will not remove this bottleneck.',severity:'High',owner:'Leo Bennett',status:'Investigating'},{id:'INC-081',project:'P03',title:'Calibration check completed',detail:'Equipment readiness verified by team lead.',severity:'Low',owner:'Nora Martin',status:'Resolved'}],audit:[],extraQA:{P01:0,P02:0,P03:0},outage:false,...initialWorkflow()};}
export function metrics(s,id){const p=projects.find(p=>p.id===id),w=s.workers.filter(w=>w.project===id&&w.status==='Collecting');const rawRate=w.reduce((n,w)=>n+w.units,0)*(s.outage&&id==='P01'?0.65:1);const passRate=p.firstPass/p.firstReviews;const collectable=Math.floor(rawRate*4*passRate);const backlog=p.submitted-p.reviewed;const reviewable=Math.floor((p.qaRate+(s.extraQA[id]||0))*4*passRate);const incremental=Math.min(collectable+Math.floor(backlog*passRate),reviewable);const forecast=p.accepted+incremental;const cost=w.reduce((n,w)=>n+w.hourly*4,0)+(s.extraQA[id]||0)*4*3;return {...p,active:w.length,rawRate,passRate,backlog,forecast,shortfall:Math.max(0,p.target-forecast),coverage:Math.min(100,w.length/16*100),cost,incremental,costPerUnit:incremental?cost/incremental:null,limited:reviewable<collectable+Math.floor(backlog*passRate)?'QA capacity':'Collection capacity'};}
export function eligibility(s,worker,id){if(!worker)return 'Worker not found';if(worker.status!=='Available'||worker.project)return 'Worker is unavailable or already assigned';if(!worker.qualified.includes(id))return 'Missing project qualification';return null;}
export function assign(s,workerId,id){if(!projects.some(p=>p.id===id))throw Error('Unknown project');const w=s.workers.find(w=>w.id===workerId);const error=eligibility(s,w,id);if(error)throw Error(error);w.project=id;w.status='Collecting';s.audit.unshift({time:new Date().toISOString(),action:`Assigned ${w.name} (${w.id}) to ${projects.find(p=>p.id===id).name}`});}
export function addQA(s,id){if(!projects.some(p=>p.id===id))throw Error('Unknown project');if(s.extraQA[id]>=12)throw Error('Reserve QA capacity already allocated');s.extraQA[id]+=6;s.audit.unshift({time:new Date().toISOString(),action:`Added 6 review units/hour to ${projects.find(p=>p.id===id).name}; modeled reserve QA cost $72 over 4 hours`});}
export function totals(s){return projects.map(p=>metrics(s,p.id));}
